             --run ${patchModelStats} \
-            --set-default OPENCODE_MEMORY_RECALL_MODEL ko-ag/glm
+            --set-default OPENCODE_MEMORY_RECALL_MODEL zai-coding-plan/glm-5.3-flash
         '';
       };
     })

